UPDATE finance_account
SET is_default = 0, update_time = #{now}
WHERE channel = #{channel} AND is_deleted = 0 AND is_default = 1

    AND id <> #{excludeId}

UPDATE finance_account
SET is_default = 1, update_time = #{now}
WHERE id = #{id} AND is_deleted = 0

UPDATE finance_account
SET status = #{status}, update_time = #{now}
WHERE id = #{id} AND is_deleted = 0

UPDATE finance_account
SET is_deleted = 1, is_default = 0, update_time = #{now}
WHERE id = #{id} AND is_deleted = 0

UPDATE finance_account
SET is_deleted = 0, account_name = #{accountName}, is_default = #{isDefault},
    status = #{status}, remark = #{remark}, update_time = #{now}
WHERE id = #{id}
